        inputFolder = headShaOrInputFolder;
        jenkinsBasePath = inputFolderOpt;
    } else {
        owner = scmOrOwner;
        repo = repoOrHeadSha;
        headSha = headShaOrInputFolder;
        inputFolder = inputFolderOpt;
        jenkinsBasePath = jenkinsBasePathOpt;
